import {useMutation, useSuspenseQuery} from "@tanstack/react-query";

import {EntryList} from "./-local/entry-list";
import {fetchEntries, postEntry} from "./entry-api";

export const EntriesPage = () => {
  const responseEntries = useSuspenseQuery({
    queryKey: ["entries"],
    queryFn: fetchEntries,
    select: (response) => ({
      items: response.entries.map((entry) => ({id: entry.id, label: entry.title.trim()})),
      meta: {total: response.total},
    }),
  });
  const mutationEntry = useMutation({mutationFn: postEntry});

  return (
    <EntryList
      items={responseEntries.data.items}
      total={responseEntries.data.meta.total}
      onCreate={mutationEntry.mutate}
    />
  );
};
